from collections import Counter
from copy import deepcopy

test_input = [
    [9, 9, 9, 9, 9, 9, 9, 8, 9],
    [9, 5, 2, 9, 1, 9, 9, 6, 1],
    [3, 9, 9, 9, 9, 9, 9, 6, 9],
    [9, 7, 9, 9, 7, 9, 9, 9, 8],
    [0, 0, 0, 0, 0, 0, 0, 0, 0],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9]
]

# Find colors appearing exactly once in entire top half
all_colors = {}
for i in range(4):
    for j in range(9):
        val = test_input[i][j]
        if val != 9:
            if val not in all_colors:
                all_colors[val] = []
            all_colors[val].append((i, j))

print("Global color counts:")
unique_colors = {}
for color, positions in all_colors.items():
    print(f"  Color {color}: {len(positions)} at {positions}")
    if len(positions) == 1:
        unique_colors[color] = positions[0]

print(f"\nUnique colors (appearing once): {list(unique_colors.keys())}")

# Protocol: for each unique color, propagate to rows at distance 3
output = [row.copy() for row in test_input]

for color, (row, col) in unique_colors.items():
    tar_rows = [row - 3, row + 3]
    for tar_row in tar_rows:
        if 0 <= tar_row < 9 and tar_row != 4 and output[tar_row][col] == 9:
            output[tar_row][col] = color
            print(f"Propagating color {color} from ({row},{col}) to ({tar_row},{col})")

print("\nOutput:")
for row in output:
    print(row)

